<script setup lang="ts">
import {computed} from 'vue'
import {ArrowLeft,Heart} from 'lucide-vue-next'
import type {ServerItem} from '../workspace'
import type {Account} from '../../sources/contracts'
import ServerArtwork from '../ServerArtwork.vue'
import ServerPosterRow from './ServerPosterRow.vue'
const props=defineProps<{person:ServerItem;account:Account;items:ServerItem[]}>(),emit=defineEmits<{back:[];select:[item:ServerItem];favorite:[];more:[kind:string]}>()
const sections=computed(()=>[{key:'movie',title:'电影',items:props.items.filter(i=>i.kind==='movie')},{key:'series',title:'电视剧',items:props.items.filter(i=>['series','show'].includes(i.kind))},{key:'episode',title:'剧集',items:props.items.filter(i=>i.kind==='episode')},{key:'other',title:'其他',items:props.items.filter(i=>!['movie','series','show','episode'].includes(i.kind))}].filter(s=>s.items.length))
</script>
<template><div class="media-server-workspace"><div class="detail-page"><div class="person-shell"><div class="person-hero"><ServerArtwork v-if="person.backdropPath" class="person-hero-backdrop" :account="account" :path="person.backdropPath" :alt="person.name"/><div v-else class="person-hero-backdrop person-hero-backdrop-fallback"/><div class="person-hero-mask"/><div class="detail-top-back"><button class="detail-back-button" @click="emit('back')"><ArrowLeft :size="20"/><span>返回</span></button></div><div class="person-hero-overlay"><div class="person-hero-card-row"><div class="person-hero-poster media-image-frame"><ServerArtwork :account="account" :path="person.imagePath" :alt="person.name"/></div><div class="person-shelf-panel"><div class="person-shelf-heading"><h1>{{person.name}}</h1><button class="detail-square-action" :class="{active:person.favorite}" :aria-label="person.favorite?'取消收藏':'收藏'" @click="emit('favorite')"><Heart :size="20" :fill="person.favorite?'currentColor':'none'"/></button></div><div class="person-shelf-body"><div v-if="person.birthday" class="person-bio-row person-bio-row-inline"><span>出生</span><strong>{{person.birthday}}</strong></div><div v-if="person.birthPlace" class="person-bio-row person-bio-row-inline"><span>出生地</span><strong>{{person.birthPlace}}</strong></div><div v-if="person.deathDate" class="person-bio-row person-bio-row-inline"><span>逝世</span><strong>{{person.deathDate}}</strong></div><p v-if="person.overview" class="person-shelf-overview">{{person.overview}}</p></div></div></div></div></div><div class="person-content"><div class="person-content-divider"/><section v-for="section in sections" :key="section.key" class="detail-section person-section"><ServerPosterRow :title="section.title" :items="section.items" :account="account" :landscape="section.key==='episode'" more @more="emit('more',section.key)" @select="emit('select',$event)"/></section></div></div></div></div></template><style scoped src="./workspace.css"></style><style src="./workspace-overrides.css"></style>